export const TEST20_EXECUTABLE_PATH = '/workspace/dataset/test20_executable';

export const HELP_OPTION = '--help';
export const SHORT_HELP_OPTION = '-h';
export const LONG_OPTIONS = new Set(['--a', '--b']);

const NEGATIVE_NUMBER_PATTERN =
  /^-(?:\d+|\d*\.\d+)(?:[eE][+-]?\d+)?$/;

export function isHelpToken(token) {
  return (
    token === SHORT_HELP_OPTION ||
    (token.startsWith('--') &&
      token !== '--' &&
      HELP_OPTION.startsWith(token))
  );
}

export function isNegativeNumberToken(token) {
  return NEGATIVE_NUMBER_PATTERN.test(token);
}

import {
  isHelpToken,
  isNegativeNumberToken,
  LONG_OPTIONS,
} from './constants.mjs';

function buildFailure(reason) {
  return { ok: false, reason };
}

function isInlineAssignment(token, optionName) {
  return token.startsWith(`${optionName}=`);
}

function isOptionLikeValue(token) {
  return token.startsWith('-') && !isNegativeNumberToken(token);
}

export function parseArgs(argv) {
  const values = { a: undefined, b: undefined };

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      return buildFailure('end_of_options');
    }

    if (isHelpToken(token)) {
      return buildFailure('help');
    }

    if (token === '--a' || token === '--b') {
      const next = argv[index + 1];

      if (next === undefined || isOptionLikeValue(next)) {
        return buildFailure(`missing_value_for_${token.slice(2)}`);
      }

      values[token.slice(2)] = next;
      index += 1;
      continue;
    }

    if (isInlineAssignment(token, '--a')) {
      values.a = token.slice('--a='.length);
      continue;
    }

    if (isInlineAssignment(token, '--b')) {
      values.b = token.slice('--b='.length);
      continue;
    }

    if (LONG_OPTIONS.has(token)) {
      return buildFailure(`missing_value_for_${token.slice(2)}`);
    }

    return buildFailure('unrecognized_argument');
  }

  if (values.a === undefined || values.b === undefined) {
    return buildFailure('missing_required_argument');
  }

  return { ok: true, values };
}

export function buildCanonicalArgv(values) {
  return ['--a', values.a, '--b', values.b];
}

import { spawnSync } from 'node:child_process';
import { accessSync, constants as fsConstants } from 'node:fs';

import { TEST20_EXECUTABLE_PATH } from './constants.mjs';

export function resolveExecutablePath() {
  accessSync(TEST20_EXECUTABLE_PATH, fsConstants.X_OK);
  return TEST20_EXECUTABLE_PATH;
}

export function runExecutable(argv, executablePath = resolveExecutablePath()) {
  const result = spawnSync(executablePath, argv, { stdio: 'inherit' });

  if (result.error) {
    throw result.error;
  }

  if (result.signal) {
    process.kill(process.pid, result.signal);
    return 1;
  }

  return result.status ?? 1;
}

